-- LobeHub's tables on D1 (users, settings, agents, sessions, topics, messages,
-- providers, ...). GENERATED by scripts/generateD1LobeSchema.mts from
-- packages/database/src/schemas; do not edit by hand. Idempotent.
--
-- The Worker reaches these through the D1 driver in
-- packages/database/src/core/d1 when DATABASE_DRIVER=d1. LobeHub's `documents`
-- table is `lobe_documents` here, because QwkSearch already has `documents`.

CREATE TABLE IF NOT EXISTS "agents" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "slug" TEXT,
  "title" TEXT,
  "name" TEXT,
  "description" TEXT,
  "tags" TEXT DEFAULT '[]',
  "editor_data" TEXT,
  "avatar" TEXT,
  "background_color" TEXT,
  "market_identifier" TEXT,
  "metadata" TEXT,
  "profile" TEXT,
  "society_id" TEXT,
  "plugins" TEXT,
  "client_id" TEXT,
  "user_id" TEXT NOT NULL,
  "workspace_id" TEXT,
  "agency_config" TEXT,
  "chat_config" TEXT,
  "few_shots" TEXT,
  "model" TEXT,
  "params" TEXT DEFAULT '{}',
  "provider" TEXT,
  "system_role" TEXT,
  "tts" TEXT,
  "virtual" INTEGER DEFAULT 0,
  "pinned" INTEGER,
  "opening_message" TEXT,
  "opening_questions" TEXT DEFAULT '[]',
  "session_group_id" TEXT,
  "visibility" TEXT NOT NULL DEFAULT 'public',
  "deleted_at" TEXT,
  "is_deleted" INTEGER,
  "accessed_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  "created_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  "updated_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE ON UPDATE NO ACTION,
  FOREIGN KEY ("workspace_id") REFERENCES "workspaces" ("id") ON DELETE CASCADE ON UPDATE NO ACTION,
  FOREIGN KEY ("session_group_id") REFERENCES "session_groups" ("id") ON DELETE SET NULL ON UPDATE NO ACTION
);

CREATE UNIQUE INDEX IF NOT EXISTS "client_id_user_id_unique" ON "agents" ("client_id", "user_id");

CREATE UNIQUE INDEX IF NOT EXISTS "agents_slug_user_id_unique" ON "agents" ("slug", "user_id") WHERE "workspace_id" is null;

CREATE INDEX IF NOT EXISTS "agents_created_at_idx" ON "agents" ("created_at");

